<?php require __DIR__.'/config.php';method_is('POST');$d=body_json();$name=trim((string)($d['full_name']??''));$email=strtolower(trim((string)($d['email']??'')));$pass=(string)($d['password']??'');if($name===''||mb_strlen($name)>120||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8)json_out(['error'=>'Enter a name, valid email, and password of at least 8 characters.'],422);try{$s=$pdo->prepare("INSERT INTO users(full_name,email,password_hash,role) VALUES(?,?,?,'customer')");$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);}catch(PDOException $e){if($e->getCode()==='23000')json_out(['error'=>'This email is already registered.'],409);json_out(['error'=>'Unable to create account.'],500);}session_regenerate_id(true);$_SESSION['user']=['id'=>(int)$pdo->lastInsertId(),'full_name'=>$name,'email'=>$email,'role'=>'customer'];json_out(['user'=>$_SESSION['user']],201);?>